/* ======================================================================
   SastoukaStore — PATCH 2.5 : GLOBAL A4 PORTRAIT
   Toutes les couvertures de supports numériques utilisent le même ratio.
   A4 = 210 / 297 = 0.70707
   ====================================================================== */

/* ---------- Catalogue public / premium17 ---------- */
.product-grid .premium-product .product-media{
  aspect-ratio:210 / 297;
  width:100%;
  height:auto;
  min-height:0;
  background:#EAF4FC;
  position:relative;
  overflow:hidden;
  display:block;
}

.product-grid .premium-product .product-media img{
  display:block;
  width:100%;
  height:100%;
  max-width:100%;
  max-height:100%;
  object-fit:contain;
  object-position:center center;
}

/* ---------- Fiche produit / premium16 ---------- */
.detail-grid .detail-media{
  width:100%;
  height:auto;
  aspect-ratio:210 / 297;
  min-height:0;
  background:#E5EEF7;
  position:relative;
  overflow:hidden;
  display:flex;
  align-items:center;
  justify-content:center;
}

.detail-grid .detail-media img{
  display:block;
  width:100%;
  height:100%;
  max-width:100%;
  max-height:100%;
  object-fit:contain;
  object-position:center center;
}

/* ---------- Panier ---------- */
.cart-item .mini-cover{
  width:76px;
  height:auto;
  aspect-ratio:210 / 297;
  min-height:0;
  background:#EAF4FC;
  display:flex;
  align-items:center;
  justify-content:center;
  overflow:hidden;
  border-radius:10px;
}

.cart-item .mini-cover img{
  display:block;
  width:100%;
  height:100%;
  max-width:100%;
  max-height:100%;
  object-fit:contain;
  object-position:center center;
}

/* ---------- Administration numérique ---------- */
.digital-grid .digital-card .cover{
  width:100%;
  height:auto;
  aspect-ratio:210 / 297;
  min-height:0;
  background:#EAF4FC;
  position:relative;
  overflow:hidden;
  display:flex;
  align-items:center;
  justify-content:center;
}

.digital-grid .digital-card .cover img{
  display:block;
  width:100%;
  height:100%;
  max-width:100%;
  max-height:100%;
  object-fit:contain;
  object-position:center center;
}

/* ---------- Prévisualisation d'une couverture lors de la modification ---------- */
.edit-image{
  width:180px;
  height:auto;
  aspect-ratio:210 / 297;
  max-width:180px;
  max-height:255px;
  object-fit:contain;
  object-position:center center;
  display:block;
  background:#EAF4FC;
  border-radius:14px;
}

/* ---------- Ancien catalogue admin ---------- */
.admin-product-image{
  width:90px;
  height:auto;
  aspect-ratio:210 / 297;
  min-height:0;
  background:#f3f4f6;
  display:flex;
  align-items:center;
  justify-content:center;
  overflow:hidden;
}

.admin-product-image img{
  width:100%;
  height:100%;
  max-width:100%;
  max-height:100%;
  object-fit:contain;
  object-position:center center;
}

/* ---------- Responsive ---------- */
@media (max-width:1100px){
  .product-grid{
    grid-template-columns:repeat(3,minmax(0,1fr));
  }
}

@media (max-width:900px){
  .product-grid{
    grid-template-columns:repeat(3,minmax(0,1fr));
  }

  .detail-grid .detail-media{
    aspect-ratio:210 / 297;
  }

  .cart-item .mini-cover{
    width:70px;
  }
}

@media (max-width:750px){
  .product-grid{
    grid-template-columns:repeat(2,minmax(0,1fr));
  }

  .edit-image{
    width:150px;
    max-width:150px;
    max-height:212px;
  }
}

@media (max-width:480px){
  .product-grid{
    grid-template-columns:repeat(2,minmax(0,1fr));
  }

  .cart-item .mini-cover{
    width:64px;
  }

  .admin-product-image{
    width:60px;
  }
}

