    max-width:42px !important;
    max-height:42px !important;
    flex-basis:42px !important;
  }

  .vip-brand-mark img.chariow-header-logo,
  .p64-brand img.chariow-header-logo,
  .topbar .brand img.chariow-header-logo,
  .premium-brand img.chariow-header-logo,
  .admin-brand img.chariow-header-logo,
  .brand img.chariow-header-logo,
  img.chariow-header-logo{
    width:40px !important;
    height:40px !important;
    min-width:40px !important;
    min-height:40px !important;
    max-width:40px !important;
    max-height:40px !important;
    flex-basis:40px !important;
  }

  .vip-brand-word,
  .p64-brand-word,
  .premium-brand .brand-word,
  .topbar .brand strong,
  .admin-brand-word,
  .brand strong{
    font-size:16px !important;
  }

  .vip-nav-actions,
